import{_ as i,o as a,c as o,ag as t}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse(`{"title":"'My first mod' - Making a new Civilization","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Making-a-new-Civilization.md","filePath":"Modders/Making-a-new-Civilization.md"}`),n={name:"Modders/Making-a-new-Civilization.md"};function r(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="my-first-mod-making-a-new-civilization" tabindex="-1">&#39;My first mod&#39; - Making a new Civilization <a class="header-anchor" href="#my-first-mod-making-a-new-civilization" aria-label="Permalink to &quot;&#39;My first mod&#39; - Making a new Civilization&quot;">​</a></h1><p>By the end of this tutorial, you should have a working, generally-available mod that adds a new Civilization to the game</p><h2 id="create-your-repository" tabindex="-1">Create your repository <a class="header-anchor" href="#create-your-repository" aria-label="Permalink to &quot;Create your repository&quot;">​</a></h2><ul><li>Create a <a href="https://github.com/join" target="_blank" rel="noreferrer">Github account</a>, if you don&#39;t already have one</li><li>Go to the <a href="https://github.com/yairm210/Unciv-mod-example" target="_blank" rel="noreferrer">mod example</a></li><li>Click the green <code>Use this template</code> button - <code>Create a new repository</code></li><li>Choose your repository name and click <code>Create repository from template</code> (keep setting on &#39;public&#39;!)</li><li>Your new repository is now available!</li></ul><h2 id="fill-in-your-nation-info" tabindex="-1">Fill in your Nation info <a class="header-anchor" href="#fill-in-your-nation-info" aria-label="Permalink to &quot;Fill in your Nation info&quot;">​</a></h2><p>Each civ has some basic information - what the civ name is, the leader&#39;s name, colors and city names.</p><p>In addition, each civ has flavor text when declaring war, intoduction etc.</p><p>All of these need to be filled in in <code>jsons/Nations.json</code> file - see <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Nations.json" target="_blank" rel="noreferrer">here</a> for the base game file for more examples</p><h2 id="get-your-civ-icon" tabindex="-1">Get your Civ icon <a class="header-anchor" href="#get-your-civ-icon" aria-label="Permalink to &quot;Get your Civ icon&quot;">​</a></h2><p>Each civ has an icon, like the wreath for Rome, for instant identification.</p><p>All of these icons are white on a transparent background, and are 100x100 pixels - see <a href="#icon-considerations">icon considerations</a> for details</p><p>You&#39;ll need to put your icon in the <code>Images/NationIcons</code> folder - you can navigate there and click <code>Add file - Create a new file</code> (top-right corner)</p><h2 id="test-it-out" tabindex="-1">Test it out! <a class="header-anchor" href="#test-it-out" aria-label="Permalink to &quot;Test it out!&quot;">​</a></h2><ul><li>Open Unciv</li><li>Click &#39;Mods&#39; - &#39;Download mod from URL&#39;</li><li>Copy-paste your repository&#39;s URL to the textbox, and click &#39;Download&#39;</li><li>Exit the mod screen, and create a new game, selecting your mod - which will be under &#39;Extension mods&#39; on the left</li></ul><p>Congrats, your Civ is now fully playable!</p><div class="custom-block note"><p>You currently won&#39;t see any images from this mod, since it has no texture atlas - see <a href="./Images-and-Audio.html#images-and-the-texture-atlas">here</a> for more details If you&#39;re on Desktop, you can restart Unciv to generate this atlas and see the images</p></div><p>But this nation&#39;s abilities are exactly those of the base mod. To make it truly unique, we&#39;ll need to change some Uniques 😉</p><h2 id="adding-unique-units" tabindex="-1">Adding unique units <a class="header-anchor" href="#adding-unique-units" aria-label="Permalink to &quot;Adding unique units&quot;">​</a></h2><p>Units are defined in the <code>jsons/Units.json</code> - for the base game file, see <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Units.json" target="_blank" rel="noreferrer">here</a> file, with an icon in the <a href="https://github.com/yairm210/Unciv/tree/master/android/Images.Construction/UnitIcons" target="_blank" rel="noreferrer">UnitIcons</a> folder.</p><p>The icons must be 200x200 pixels, white on transparent background - see <a href="#icon-considerations">icon considerations</a> for details - and go in the <code>Images/UnitIcons</code> folder</p><p>Remember that these are unique units, so search for an existing unique unit to see how they replace their regular counterparts!</p><h2 id="adding-unique-buildings" tabindex="-1">Adding unique buildings <a class="header-anchor" href="#adding-unique-buildings" aria-label="Permalink to &quot;Adding unique buildings&quot;">​</a></h2><p>Same as the units - info is in <code>jsons/Buildings.json</code> - for the base game file, see <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Buildings.json" target="_blank" rel="noreferrer">Buildings.json</a> file and icons in the <a href="https://github.com/yairm210/Unciv/tree/master/android/Images.Construction/BuildingIcons" target="_blank" rel="noreferrer">BuildingIcons</a> folder, same rules for the icons apply (200x200 pixels, icon considerations)</p><p>Icons go in <code>Images/BuildingIcons</code></p><h2 id="civ-unique" tabindex="-1">Civ Unique <a class="header-anchor" href="#civ-unique" aria-label="Permalink to &quot;Civ Unique&quot;">​</a></h2><p>Check out our <a href="./uniques.html">list of uniques</a> to see all the cool special effects you can add to your civilization!</p><h2 id="make-it-searchable" tabindex="-1">Make it searchable! <a class="header-anchor" href="#make-it-searchable" aria-label="Permalink to &quot;Make it searchable!&quot;">​</a></h2><p>To list your mod in the Unciv Mods screen:</p><ul><li>Open your repository</li><li>Click the gear icon, to the right of the &#39;About&#39; label (right side, top)</li><li>Under &#39;Topics&#39;, add &#39;unciv-mod&#39;</li><li>&#39;Save changes&#39;</li></ul><p>Congrats, your mod will now be shown in the mods page!</p><p>The more stars your repo has, the higher towards the top it will appear, so start gaining fans 😄</p><h2 id="icon-considerations" tabindex="-1">Icon considerations <a class="header-anchor" href="#icon-considerations" aria-label="Permalink to &quot;Icon considerations&quot;">​</a></h2><p>ALL icons must be legally acceptable, meaning they either come from from open sources or you act according to their licence (for Creative Commons, for instance, you have to specify the source and the creator).</p><p>Icons directly from the base game belong to Firaxis, so I&#39;m not sure we&#39;re legally allowed to use them - please use other sources!</p><p>One source I use constantly is <a href="https://thenounproject.com" target="_blank" rel="noreferrer">The Noun Project</a> - everything there is Creative Commons or open, so they can all be used!</p><p>Credits for icons should go in a <code>Credits.md</code> page.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><p>You have a working mod, now it&#39;s time to go wild!</p><ul><li>Add the <a href="./Images-and-Audio.html#images-and-the-texture-atlas">atlas files</a> to your repo so your users get images</li><li>Install Git locally, so you can change your files on your device and have those changes reflected in your repository</li><li>Expand the abilities of your civ by adding new <a href="./uniques.html">uniques</a></li><li>Add new civs, buildings or units</li><li>Expand into other game objects by exploring the rest of the <a href="./Mod-file-structure/1-Overview.html">mod file structure</a></li><li>Try creating a base ruleset <a href="https://github.com/yairm210/Unciv-minimal-base-ruleset" target="_blank" rel="noreferrer">from this template</a></li></ul>',39)])])}const p=i(n,[["render",r]]);export{m as __pageData,p as default};
